import hashlib,json,struct

def canonical(value):
    return json.dumps(value,ensure_ascii=False,sort_keys=True,separators=(",",":"),allow_nan=False).encode("utf-8")

def digest(tag,value):
    parts=(tag.encode(),canonical(value))
    return hashlib.sha256(b"".join(struct.pack(">I",len(p))+p for p in parts)).hexdigest()

def core_hash(core):
    leaves=[{"schema":c["schema"],"entity_id":c["entity_id"],"hash":digest("component/v1",c)} for c in core["components"]]
    queue=[{"event_id":q["event"]["header"]["event_id"],"hash":digest("pending-event/v1",q)} for q in core["pending"]]
    return digest("core-root/v1",{**core,"components":leaves,"pending":queue})

def project(core,protocol):
    components=[{"kind":c["schema"]["kind"],"version":c["schema"]["version"],"entity_id":c["entity_id"],"body_hex":canonical(c).hex(),"sha256":digest("component/v1",c)} for c in core["components"]]
    pending=[{"event_id":q["event"]["header"]["event_id"],"ordinal":i,"body_hex":canonical(q).hex(),"sha256":digest("pending-event/v1",q)} for i,q in enumerate(core["pending"])]
    streams=[{"stream_id":s["stream_id"],"body_hex":canonical(s).hex()} for s in protocol["streams"]]
    receipts=[{"command_id":r["command"]["command_id"],"revision":r["receipt"]["revision"],"body_hex":canonical(r).hex()} for r in protocol["receipts"]]
    return {"core_meta_hex":canonical({k:v for k,v in core.items() if k not in ("components","pending")}).hex(),"protocol_meta_hex":canonical({k:v for k,v in protocol.items() if k not in ("streams","receipts")}).hex(),"core_hash":core_hash(core),"protocol_hash":digest("protocol/v1",protocol),"components":components,"pending":pending,"streams":streams,"receipts":receipts}

def difference(old,new):
    result={}
    for group,keys in (("components",("kind","version","entity_id")),("pending",("event_id",)),("streams",("stream_id",)),("receipts",("command_id",))):
        left={tuple(row[k] for k in keys):row for row in old[group]}
        right={tuple(row[k] for k in keys):row for row in new[group]}
        result[group+"_upserts"]=[right[k] for k in sorted(right) if right[k]!=left.get(k)]
        result[group+"_deletes"]=[list(k) for k in sorted(left) if k not in right]
    return result

def derive(fixture):
    previous=project(fixture["initial_core"],fixture["initial_protocol"])
    initial=previous
    vectors=[]
    for i,step in enumerate(fixture["trace"]["steps"]):
        witness=step["witness"]
        next_rows=project(witness["core"],witness["protocol"])
        assert next_rows["core_hash"]==step["core_hash"]
        assert next_rows["protocol_hash"]==step["protocol_hash"]
        commit=step["outcome"]["kind"]=="committed" and witness["protocol"]["revision"]==json.loads(bytes.fromhex(previous["protocol_meta_hex"]))["revision"]+1
        body={key:step[key] for key in ("command","outcome","core_hash","protocol_hash","facts_hash","diff_hash")}
        vectors.append({"input_step":i,"new_commit":commit,"tick":witness["core"]["tick"],"revision":witness["protocol"]["revision"],"outcome":step["outcome"],"rows":next_rows,"row_changes":difference(previous,next_rows),"replay_body_hex":canonical(body).hex() if commit else None,"replay_sha256":digest("save-step/v1",body) if commit else None})
        previous=next_rows
    checkpoint={"core":fixture["initial_core"],"protocol":fixture["initial_protocol"],"header":fixture["trace"]["header"]}
    return {"initial_rows":initial,"initial_checkpoint_body_hex":canonical(checkpoint).hex(),"initial_checkpoint_sha256":digest("save-checkpoint/v1",checkpoint),"steps":vectors,"committed_steps":[v["input_step"] for v in vectors if v["new_commit"]]}

